"use client";
import { useState } from "react";

type Category = {
  id: string;
  slug: string;
  name: string;
  iconEmoji: string | null;
  tags: string[];
  imageBase64: string | null;
  _count: { posts: number; components: number };
};

export default function HomeCategoryLayout({ categories }: { categories: Category[] }) {
  const [activeSlug, setActiveSlug] = useState<string | null>(null);

  const left = categories.slice(0, 5);
  const right = categories.slice(5, 9);
  const activeCategory = categories.find((c) => c.slug === activeSlug) ?? null;

  return (
    <div className="main-layout">
      {/* LEFT COLUMN */}
      <div className="col-left">
        {left.map((cat) => (
          <a
            key={cat.id}
            className={`cat-cluster${activeSlug === cat.slug ? " active" : ""}`}
            href={`/category/${cat.slug}`}
            onMouseEnter={() => setActiveSlug(cat.slug)}
            onMouseLeave={() => setActiveSlug(null)}
          >
            <span className="cat-name">{cat.iconEmoji} {cat.name}</span>
            <span className="cat-tags">{cat.tags.join(" · ")}</span>
            <span className="cat-count">{cat._count.posts} threads</span>
          </a>
        ))}
      </div>

      {/* CENTER LOGO */}
      <div className="center-logo">
        <div className={`logo-image-wrapper${activeSlug ? " active" : ""}`}>
          {/* Default SVG */}
          <div className="logo-default" style={{ opacity: activeSlug ? 0 : 1 }}>
           <img src="data:image/png;base64," alt="" />
          </div>

          {/* Per-category images (stored in DB) */}
          {categories.map((cat) =>
            cat.imageBase64 ? (
              <div
                key={cat.slug}
                className={`logo-category-img${activeSlug === cat.slug ? " visible" : ""}`}
              >
                <img src={cat.imageBase64} alt={cat.name} />
              </div>
            ) : null
          )}

          {/* Fallback emoji for categories without an image */}
          {activeCategory && !activeCategory.imageBase64 && (
            <div className="logo-category-img visible">
              <span style={{ fontSize: "5rem" }}>{activeCategory.iconEmoji}</span>
            </div>
          )}
        </div>
      </div>

      {/* RIGHT COLUMN */}
      <div className="col-right">
        {right.map((cat) => (
          <a
            key={cat.id}
            className={`cat-cluster${activeSlug === cat.slug ? " active" : ""}`}
            href={`/category/${cat.slug}`}
            onMouseEnter={() => setActiveSlug(cat.slug)}
            onMouseLeave={() => setActiveSlug(null)}
          >
            <span className="cat-name">{cat.iconEmoji} {cat.name}</span>
            <span className="cat-tags">{cat.tags.join(" · ")}</span>
            <span className="cat-count">{cat._count.posts} threads</span>
          </a>
        ))}
      </div>
    </div>
  );
}
